package com.cryptostrategy.platform.backtesting.internal;import com.cryptostrategy.platform.backtesting.api.model.*;import java.util.*;public final class BacktestReproductionVerifier{public BacktestVerificationReport verify(BacktestResult original,BacktestResult reproduced){List<String> differences=new ArrayList<>();if(!original.provenance().equals(reproduced.provenance()))differences.add("provenance");if(!original.assumptions().equals(reproduced.assumptions()))differences.add("assumptions");if(!semanticTrades(original.trades()).equals(semanticTrades(reproduced.trades())))differences.add("trades");if(!original.equityCurveSummary().equals(reproduced.equityCurveSummary()))differences.add("equitySummary");if(!original.fingerprint().equals(reproduced.fingerprint()))differences.add("backtestFingerprint");return new BacktestVerificationReport(differences.isEmpty(),differences);}private static List<String> semanticTrades(List<Trade> trades){return trades.stream().map(t->t.sequence()+"|"+t.entryTime()+"|"+t.exitTime()+"|"+t.entryPrice().value()+"|"+t.exitPrice().value()+"|"+t.quantity().value()+"|"+t.entryFee().value()+"|"+t.exitFee().value()+"|"+t.realizedPnl()).toList();}}
